        #[inline]
        pub fn set_team_color(team_id: i32, color: TeamColor) -> Result<bool> {
            let value = crate::generated::display::set_team_color(team_id, crate::generated::display::TeamColor { r: color.r, g: color.g, b: color.b, a: color.a })?;
            Ok(value)
        }

