        #[inline]
        pub fn set_projectile_ceg(projectile_id: i32, ceg_name: &str) -> Result<i32> {
            let mut ceg_name_bytes = ceg_name.as_bytes().to_vec();
            if ceg_name_bytes.contains(&0) { return Err(crate::ApiError::new(crate::ErrorCode::InvalidArgument as i32)); }
            ceg_name_bytes.push(0);
            let ceg_name_cstr = core::ffi::CStr::from_bytes_with_nul(&ceg_name_bytes).map_err(|_| crate::ApiError::new(crate::ErrorCode::InvalidArgument as i32))?;
            crate::generated::borrowed::projectile_control::set_projectile_ceg(projectile_id, &ceg_name_cstr)
        }

        #[inline]
        pub fn set_projectile_collision(projectile_id: i32) -> Result<bool> {
            let value = crate::generated::projectile_control::set_projectile_collision(projectile_id)?;
            Ok(value)
        }

        #[inline]
        pub fn set_projectile_damages(projectile_id: i32, unused: i32, damage_key: &str, damage_value: f32) -> Result<bool> {
            let mut damage_key_bytes = damage_key.as_bytes().to_vec();
            if damage_key_bytes.contains(&0) { return Err(crate::ApiError::new(crate::ErrorCode::InvalidArgument as i32)); }
            damage_key_bytes.push(0);
            let damage_key_cstr = core::ffi::CStr::from_bytes_with_nul(&damage_key_bytes).map_err(|_| crate::ApiError::new(crate::ErrorCode::InvalidArgument as i32))?;
            crate::generated::borrowed::projectile_control::set_projectile_damages(projectile_id, unused, &damage_key_cstr, damage_value)
        }

