        #[inline]
        pub fn spawn_explosion(pos: Float3, dir: Float3, explosion_params: NativeExplosionParams) -> Result<bool> {
            let value = crate::generated::effects_control::spawn_explosion(crate::generated::effects_control::Float3 { x: pos.x, y: pos.y, z: pos.z }, crate::generated::effects_control::Float3 { x: dir.x, y: dir.y, z: dir.z }, crate::generated::effects_control::NativeExplosionParams { damages: explosion_params.damages, weapon_def_id: explosion_params.weapon_def_id, owner_id: explosion_params.owner_id, hit_unit_id: explosion_params.hit_unit_id, hit_feature_id: explosion_params.hit_feature_id, crater_area_of_effect: explosion_params.crater_area_of_effect, damage_area_of_effect: explosion_params.damage_area_of_effect, edge_effectiveness: explosion_params.edge_effectiveness, explosion_speed: explosion_params.explosion_speed, gfx_mod: explosion_params.gfx_mod, impact_only: explosion_params.impact_only, ignore_owner: explosion_params.ignore_owner, damage_ground: explosion_params.damage_ground, projectile_id: explosion_params.projectile_id })?;
            Ok(value)
        }

        #[inline]
        pub fn spawn_sfx(unit_id: i32, sfx_id: i32, pos: Float3, dir: Float3, radius: f32, damage: f32, absolute: bool) -> Result<bool> {
            let value = crate::generated::effects_control::spawn_sfx(unit_id, sfx_id, crate::generated::effects_control::Float3 { x: pos.x, y: pos.y, z: pos.z }, crate::generated::effects_control::Float3 { x: dir.x, y: dir.y, z: dir.z }, radius, damage, absolute)?;
            Ok(value)
        }

